:root {
  --paper: #f7f3ea;
  --card: #fffdf8;
  --ink: #1e2a26;
  --green: #26453c;
  --green-soft: #3d6b5c;
  --amber: #bd8236;
  --muted: #6a776f;
  --line: #e3dccb;
  --shadow: 0 12px 32px rgba(38, 69, 60, 0.09);
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  line-height: 1.75;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4 {
  margin: 0;
  font-family: "Noto Serif SC", "Songti SC", Georgia, serif;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: 0.01em;
}

p { margin: 0; }
a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
ul { margin: 0; padding: 0; list-style: none; }

.container {
  width: 100%;
  max-width: 1160px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------- header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(250, 247, 240, 0.94);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 74px;
}

.brand { display: flex; align-items: center; gap: 12px; }

.brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--green);
  color: #f6efe0;
  font-family: "Noto Serif SC", serif;
  font-size: 20px;
}

.brand-text { display: flex; flex-direction: column; line-height: 1.25; }
.brand-text strong { font-size: 17px; letter-spacing: 0.04em; }
.brand-text em {
  font-style: normal;
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
}

.nav { display: flex; align-items: center; gap: 6px; }

.nav-link {
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 15px;
  color: var(--green);
  transition: background 0.2s, color 0.2s;
}
.nav-link:hover { background: rgba(38, 69, 60, 0.08); }
.nav-link.router-link-exact-active { background: var(--green); color: #f8f2e2; }

.nav-hours {
  margin-left: 14px;
  padding-left: 16px;
  border-left: 1px solid var(--line);
  font-size: 13px;
  color: var(--muted);
  white-space: nowrap;
}

.nav-toggle {
  display: none;
  width: 42px;
  height: 42px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--card);
  cursor: pointer;
  padding: 11px 10px;
  flex-direction: column;
  justify-content: space-between;
}
.nav-toggle span { display: block; height: 2px; background: var(--green); border-radius: 2px; transition: transform 0.25s, opacity 0.2s; }
.nav-toggle.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-toggle.active span:nth-child(2) { opacity: 0; }
.nav-toggle.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ---------- shared ---------- */
.site-main { display: block; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 26px;
  border-radius: 999px;
  border: 1px solid transparent;
  font-size: 15px;
  background: var(--green);
  color: #f8f2e2;
  cursor: pointer;
  transition: transform 0.2s, background 0.2s, border-color 0.2s;
}
.btn:hover { transform: translateY(-2px); background: #1d372f; }
.btn.ghost { background: transparent; border-color: var(--green); color: var(--green); }
.btn.ghost:hover { background: rgba(38, 69, 60, 0.08); }

.eyebrow {
  display: inline-block;
  font-size: 12px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--amber);
  margin-bottom: 14px;
}

.section { padding: 74px 0; }
.section.tint { background: #f1ebdc; }

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 34px;
}
.section-head h2 { font-size: clamp(22px, 3vw, 30px); }
.section-head p { color: var(--muted); font-size: 15px; max-width: 520px; margin-top: 10px; }
.section-head .more { font-size: 14px; color: var(--green-soft); border-bottom: 1px solid var(--green-soft); white-space: nowrap; }

/* ---------- hero ---------- */
.hero { padding: 56px 0 0; }

.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: center;
}

.hero h1 {
  font-size: clamp(30px, 4.6vw, 50px);
  letter-spacing: 0.02em;
}
.hero h1 span { color: var(--green-soft); }

.hero-lead {
  margin-top: 20px;
  font-size: 16.5px;
  color: #46564e;
  max-width: 500px;
}

.hero-actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 30px; }

.hero-figure { position: relative; }
.hero-figure img {
  width: 100%;
  aspect-ratio: 4 / 3.2;
  object-fit: cover;
  border-radius: 20px;
  box-shadow: var(--shadow);
}
.hero-tag {
  position: absolute;
  left: -16px;
  bottom: 24px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 12px 18px;
  box-shadow: var(--shadow);
}
.hero-tag strong { display: block; font-family: "Noto Serif SC", serif; font-size: 20px; color: var(--green); }
.hero-tag span { font-size: 12.5px; color: var(--muted); letter-spacing: 0.08em; }

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 52px;
  padding: 26px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.stat strong {
  display: block;
  font-family: "Noto Serif SC", serif;
  font-size: clamp(20px, 2.4vw, 27px);
  color: var(--green);
}
.stat span { font-size: 13.5px; color: var(--muted); }

/* ---------- services ---------- */
.service-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.service {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 26px 22px;
  transition: transform 0.25s, box-shadow 0.25s;
}
.service:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
.service .icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #eef1e7;
  font-size: 20px;
  margin-bottom: 16px;
}
.service h3 { font-size: 17px; margin-bottom: 8px; }
.service p { font-size: 14px; color: var(--muted); }

/* ---------- book card ---------- */
.book-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 20px;
}

.book-card {
  display: flex;
  flex-direction: column;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  transition: transform 0.25s, box-shadow 0.25s;
}
.book-card:hover { transform: translateY(-5px); box-shadow: var(--shadow); }

.book-cover { position: relative; aspect-ratio: 3 / 3.5; background: #e8e2d4; overflow: hidden; }
.book-cover img { width: 100%; height: 100%; object-fit: cover; }

.badge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  letter-spacing: 0.04em;
  background: rgba(255, 253, 248, 0.94);
}
.badge.ok { color: #226b4c; }
.badge.out { color: #a8542d; }

.book-body { padding: 16px 16px 18px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.book-cat { font-size: 11.5px; color: var(--amber); letter-spacing: 0.1em; }
.book-title { font-size: 16.5px; }
.book-author { font-size: 13px; color: var(--muted); }
.book-sum {
  font-size: 13px;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.book-meta {
  margin-top: auto;
  padding-top: 10px;
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--green-soft);
  border-top: 1px dashed var(--line);
}

/* ---------- events ---------- */
.event-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.event {
  display: flex;
  gap: 16px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 22px;
}
.event-date {
  flex: none;
  width: 58px;
  height: 66px;
  border-radius: 12px;
  background: var(--green);
  color: #f7f1e0;
  display: grid;
  place-items: center;
  line-height: 1.15;
  text-align: center;
}
.event-date strong { display: block; font-size: 20px; font-family: "Noto Serif SC", serif; }
.event-date span { font-size: 11px; opacity: 0.8; }
.event h3 { font-size: 16px; margin-bottom: 6px; }
.event p { font-size: 13.5px; color: var(--muted); }
.event .place { margin-top: 8px; display: inline-block; font-size: 12px; color: var(--green-soft); }

/* ---------- gallery ---------- */
.gallery { display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 16px; }
.gallery figure { margin: 0; overflow: hidden; border-radius: 16px; }
.gallery img { width: 100%; height: 100%; min-height: 180px; object-fit: cover; transition: transform 0.5s; }
.gallery figure:hover img { transform: scale(1.05); }

/* ---------- quotes ---------- */
.quote-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.quote {
  background: var(--card);
  border-left: 3px solid var(--amber);
  border-radius: 6px 14px 14px 6px;
  padding: 24px;
}
.quote p { font-size: 15px; color: #3f4f47; }
.quote .who { margin-top: 14px; font-size: 13px; color: var(--muted); }

/* ---------- CTA ---------- */
.cta {
  background: var(--green);
  color: #f2ebdb;
  border-radius: 22px;
  padding: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}
.cta h2 { font-size: clamp(21px, 3vw, 28px); color: #fff9ec; }
.cta p { margin-top: 10px; font-size: 14.5px; color: #cdd8d1; max-width: 560px; }
.cta .btn { background: #f2ebdb; color: var(--green); }
.cta .btn:hover { background: #fff; }

/* ---------- catalog ---------- */
.page-head { padding: 52px 0 30px; }
.page-head h1 { font-size: clamp(26px, 3.6vw, 38px); }
.page-head p { margin-top: 12px; color: var(--muted); max-width: 620px; font-size: 15.5px; }

.search-bar {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 14px 16px;
}
.search-field { position: relative; flex: 1 1 260px; }
.search-field input {
  width: 100%;
  padding: 12px 14px 12px 40px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fdfaf3;
  font-size: 15px;
  color: var(--ink);
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.search-field input:focus { border-color: var(--green-soft); box-shadow: 0 0 0 3px rgba(61, 107, 92, 0.14); }
.search-field .glass { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); color: var(--muted); font-size: 15px; }

.check { display: inline-flex; align-items: center; gap: 8px; font-size: 14px; color: var(--green); cursor: pointer; }
.check input { width: 16px; height: 16px; accent-color: var(--green); }

.chips { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
.chip {
  padding: 7px 16px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--card);
  font-size: 13.5px;
  color: var(--green);
  cursor: pointer;
  font-family: inherit;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}
.chip:hover { border-color: var(--green-soft); }
.chip.active { background: var(--green); border-color: var(--green); color: #f8f2e2; }

.result-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 26px 0 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
  color: var(--muted);
}
.result-bar strong { color: var(--green); font-size: 15px; }
.reset {
  border: none;
  background: none;
  color: var(--amber);
  font-size: 13.5px;
  cursor: pointer;
  font-family: inherit;
}
.reset:hover { text-decoration: underline; }

.empty {
  text-align: center;
  padding: 70px 20px;
  background: var(--card);
  border: 1px dashed var(--line);
  border-radius: 18px;
}
.empty h3 { font-size: 19px; margin-bottom: 10px; }
.empty p { color: var(--muted); font-size: 14.5px; }

/* ---------- guide ---------- */
.guide-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 22px; }

.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 28px;
}
.panel h2 { font-size: 20px; margin-bottom: 6px; }
.panel .sub { font-size: 13.5px; color: var(--muted); margin-bottom: 18px; }

.hours { width: 100%; border-collapse: collapse; font-size: 14.5px; }
.hours th, .hours td { text-align: left; padding: 10px 4px; border-bottom: 1px dashed var(--line); }
.hours th { color: var(--muted); font-weight: 500; font-size: 13px; }
.hours td:last-child, .hours th:last-child { text-align: right; }
.hours tr:last-child td { border-bottom: none; }
.hours .closed { color: #a8542d; }

.info-list { display: grid; gap: 14px; font-size: 14.5px; }
.info-list li { display: flex; gap: 10px; }
.info-list .key { flex: none; width: 62px; color: var(--muted); font-size: 13.5px; }

.floor-list { display: grid; gap: 10px; }
.floor-list li {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding: 12px 14px;
  border-radius: 10px;
  background: #f8f4ea;
  font-size: 14.5px;
}
.floor-list .fl {
  flex: none;
  width: 34px;
  font-family: "Noto Serif SC", serif;
  color: var(--amber);
  font-size: 15px;
}

.steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.step {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px 20px;
}
.step .num {
  font-family: "Noto Serif SC", serif;
  font-size: 15px;
  color: var(--amber);
  margin-bottom: 10px;
}
.step h3 { font-size: 16px; margin-bottom: 8px; }
.step p { font-size: 13.5px; color: var(--muted); }

.rules { display: grid; gap: 10px; font-size: 14.5px; }
.rules li { padding-left: 18px; position: relative; color: #3f4f47; }
.rules li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 11px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green-soft);
}

details.faq {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 16px 20px;
  margin-bottom: 12px;
}
details.faq summary {
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  color: var(--green);
  list-style: none;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
details.faq summary::-webkit-details-marker { display: none; }
details.faq summary::after { content: "＋"; color: var(--amber); }
details.faq[open] summary::after { content: "－"; }
details.faq p { margin-top: 12px; font-size: 14px; color: var(--muted); }

.map-img {
  width: 100%;
  border-radius: 18px;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  border: 1px solid var(--line);
}

/* ---------- footer ---------- */
.site-footer {
  margin-top: 76px;
  background: #1d3129;
  color: #cdd8d1;
  padding: 46px 0 34px;
}
.footer-inner {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1.2fr;
  gap: 28px;
  font-size: 14px;
}
.footer-brand strong { display: block; color: #f6efdd; font-family: "Noto Serif SC", serif; font-size: 18px; margin-bottom: 10px; }
.footer-brand p { line-height: 1.9; color: #a9b9b1; }
.footer-links { display: flex; flex-direction: column; gap: 8px; }
.footer-links a { color: #cdd8d1; }
.footer-links a:hover { color: #f6efdd; }
.footer-meta { color: #93a49c; font-size: 13px; line-height: 2; }

/* ---------- responsive ---------- */
@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; gap: 34px; }
  .hero-figure img { aspect-ratio: 16 / 9; }
  .hero-tag { left: 16px; bottom: 16px; }
  .service-grid { grid-template-columns: repeat(2, 1fr); }
  .event-list, .quote-grid { grid-template-columns: 1fr 1fr; }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .gallery { grid-template-columns: 1fr 1fr; }
  .gallery figure:first-child { grid-column: 1 / -1; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 760px) {
  .container { padding: 0 16px; }
  .header-inner { min-height: 64px; }
  .nav-toggle { display: flex; }
  .nav {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    padding: 12px 16px 18px;
    background: #faf7f0;
    border-bottom: 1px solid var(--line);
    box-shadow: 0 16px 24px rgba(38, 69, 60, 0.08);
    display: none;
  }
  .nav.open { display: flex; }
  .nav-link { padding: 11px 14px; border-radius: 10px; }
  .nav-hours { margin: 6px 0 0; padding: 8px 14px 0; border-left: none; border-top: 1px solid var(--line); }
  .site-header { position: sticky; }
  .header-inner { position: relative; }

  .hero { padding-top: 34px; }
  .hero-lead { font-size: 15.5px; }
  .stats { grid-template-columns: 1fr 1fr; gap: 20px 12px; margin-top: 34px; }
  .section { padding: 52px 0; }
  .section-head { flex-direction: column; align-items: flex-start; gap: 12px; }
  .service-grid, .event-list, .quote-grid, .guide-grid, .steps { grid-template-columns: 1fr; }
  .book-grid { grid-template-columns: repeat(auto-fill, minmax(145px, 1fr)); gap: 14px; }
  .book-body { padding: 12px 12px 14px; }
  .book-title { font-size: 15px; }
  .gallery { grid-template-columns: 1fr; }
  .gallery img { min-height: 150px; }
  .cta { flex-direction: column; align-items: flex-start; padding: 30px 24px; }
  .panel { padding: 22px 18px; }
  .footer-inner { grid-template-columns: 1fr; gap: 22px; }
  .site-footer { margin-top: 56px; }
  .info-list li { flex-direction: column; gap: 2px; }
  .info-list .key { width: auto; }
}

